/* eslint-env jest */
'use strict';

const os = require('os');
const _ = require('lodash');

const yandexLogger = require('../../src');

describe('YandexLogger. Middleware. Req', () => {
    let logger;
    let stream;
    let jestFakeTimers;
    let req;
    let baseRecord;

    beforeEach(() => {
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/req')(),
            ],
        });

        req = {
            method: 'POST',
            protocol: 'https',
            hostname: 'yandex.ru',
            url: '/afisha?from=yamain',
            headers: {
                host: 'yandex.ru',
                cookie: 'yandexuid=123',
            },
            body: '<data>',
            connection: {
                remoteAddress: '127.0.0.1',
                remotePort: 43212,
            },
            blackbox: {
                uid: 123,
            },
            requestId: 'req123',
            cookies: {
                yandexuid: 'yandexuid123',
            },
        };

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен перезаписать record.req', () => {
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                method: 'POST',
                url: 'https://yandex.ru/afisha?from=yamain',
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123',
                },
                body: '<data>',
                remoteAddress: '127.0.0.1',
                remotePort: 43212,
                yandexuid: 'yandexuid123',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен построить url из свойства originalUrl', () => {
        req.originalUrl = '/original-url';
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                method: 'POST',
                url: 'https://yandex.ru/original-url',
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123',
                },
                body: '<data>',
                remoteAddress: '127.0.0.1',
                remotePort: 43212,
                yandexuid: 'yandexuid123',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('должен обработать record.req без свойства connection', () => {
        delete req.connection;
        let reqClone = _.cloneDeep(req);

        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                method: 'POST',
                url: 'https://yandex.ru/afisha?from=yamain',
                headers: {
                    host: 'yandex.ru',
                    cookie: 'yandexuid=123',
                },
                body: '<data>',
                remoteAddress: undefined,
                remotePort: undefined,
                yandexuid: 'yandexuid123',
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);

        expect(req).toStrictEqual(reqClone, 'Оригинальный объект не должен мутировать');
    });

    it('не должен падать с пустым объектом в record.req', () => {
        req = {};

        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: {
                method: 'GET',
                url: '',
                headers: undefined,
                body: undefined,
                remoteAddress: undefined,
                remotePort: undefined,
                yandexuid: undefined,
            },
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать с объектом в req.url', () => {
        req.url = {};

        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req: '[logger: failed to parse record.req]',
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без record.req', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(baseRecord);
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
